public class RedBlackTreeEducational { static class N{int k;boolean red=true;N l,r;N(int k){this.k=k;}} N root; boolean red(N n){return n!=null&&n.red;} N rotL(N h){N x=h.r;h.r=x.l;x.l=h;x.red=h.red;h.red=true;return x;} N rotR(N h){N x=h.l;h.l=x.r;x.r=h;x.red=h.red;h.red=true;return x;} void flip(N h){h.red=!h.red;h.l.red=!h.l.red;h.r.red=!h.r.red;} public void insert(int k){root=ins(root,k);root.red=false;} N ins(N h,int k){if(h==null)return new N(k);if(k<h.k)h.l=ins(h.l,k);else if(k>h.k)h.r=ins(h.r,k);if(red(h.r)&&!red(h.l))h=rotL(h);if(red(h.l)&&red(h.l.l))h=rotR(h);if(red(h.l)&&red(h.r))flip(h);return h;} int blackHeight(N n){if(n==null)return 1;int a=blackHeight(n.l),b=blackHeight(n.r);if(a!=b)throw new IllegalStateException("black-height mismatch");if(red(n)&&(red(n.l)||red(n.r)))throw new IllegalStateException("double-red violation");return a+(red(n)?0:1);} boolean invariant(){return root==null||!root.red&&blackHeight(root)>0;} public static void run(){RedBlackTreeEducational t=new RedBlackTreeEducational();for(int x:new int[]{10,20,30,15,5,1}){t.insert(x);System.out.println("insert "+x+", invariants="+t.invariant());}System.out.println("Deletion concept: double-black cases inspect sibling, recolor, rotate, and may propagate upward.\n");} public static void main(String[] args){run();}}
